+        depth: width / 2.0, slope: 0.0,
+        volume: Some(EdgeBreakVolume {
+            width, profile: BreakProfile::Flat,
+            frames: vec![BreakFrame { outward: [0.0, 0.0, 1.0], across: [0.0, 1.0, 0.0] }],
