+            return;
+        }
+        let mut cuts = vec![bounds.0, bounds.1];
+        let speed = ds.hypot(dd);
+        if let Some(radius) = self.radius().filter(|_| speed > 0.0) {
+            let (base, sign) = match self.profile {
+                BreakProfile::ConcaveBall { .. } => (depth, 1.0),
+                _ => (depth - sag(half, radius), -1.0),
+            };
